/**
 * DriveGuard — Cross-Language Parity Verification Runner.
 * Reads `scripts/validation/parity_fixtures.json` generated by Python reference engine,
 * computes exact metrics in TypeScript, and verifies mathematical parity.
 */

import * as fs from "fs";
import * as path from "path";
import {
  calculateSingleEyeEar,
  calculateYawWeightedEar,
  calculatePitchCompensatedEar,
  calculateMar,
  estimateHeadPoseFromLandmarks,
  classifyCockpitZone,
  LEFT_EYE_INDICES,
  RIGHT_EYE_INDICES,
  NormalizedLandmark,
} from "../lib/ai";

interface FixtureData {
  fixtures: Record<string, NormalizedLandmark[]>;
  python_reference: Record<
    string,
    {
      left_ear: number;
      right_ear: number;
      weighted_ear: number;
      compensated_ear: number;
      is_closed: boolean;
      mar: number;
      is_mar_valid: boolean;
      pitch_deg: number;
      yaw_deg: number;
      roll_deg: number;
      zone: string;
      is_valid_pose: boolean;
    }
  >;
}

async function runParityVerification() {
  const fixturePath = path.resolve(__dirname, "../../scripts/validation/parity_fixtures.json");
  if (!fs.existsSync(fixturePath)) {
    console.error(`Fixture file not found at: ${fixturePath}`);
    process.exit(1);
  }

  const rawJson = fs.readFileSync(fixturePath, "utf-8");
  const data: FixtureData = JSON.parse(rawJson);

  console.log("==========================================================================================================");
  console.log("               DRIVEGUARD CROSS-LANGUAGE DIRECT INPUT PARITY VERIFICATION");
  console.log("==========================================================================================================");
  console.log(
    `| Fixture Name | Metric | Python Ref | TypeScript | Absolute Diff | Tolerance | Parity Status |`
  );
  console.log(
    `|:-------------|:-------|:-----------|:-----------|:--------------|:----------|:--------------|`
  );

  let totalAssertions = 0;
  let passedAssertions = 0;
  let maxEarDiff = 0;
  let maxMarDiff = 0;

  for (const [name, lms] of Object.entries(data.fixtures)) {
    const py = data.python_reference[name];
    if (!py) continue;

    // TypeScript EAR calculations
    const leftEar = calculateSingleEyeEar(lms, LEFT_EYE_INDICES, 1.0, true);
    const rightEar = calculateSingleEyeEar(lms, RIGHT_EYE_INDICES, 1.0, true);
    const weightedEar = calculateYawWeightedEar(leftEar, rightEar, 0.0, true, true, false);
    const compensatedEar = calculatePitchCompensatedEar(weightedEar, 0.0, 0.0, 0.20);
    const isClosed = leftEar < 0.20 && rightEar < 0.20;

    // TypeScript MAR calculation
    const mar = calculateMar(lms, 1.0, true);

    // Parity checks
    const earDiff = Math.abs(weightedEar - py.weighted_ear);
    const marDiff = Math.abs(mar - py.mar);

    if (earDiff > maxEarDiff) maxEarDiff = earDiff;
    if (marDiff > maxMarDiff) maxMarDiff = marDiff;

    const earPassed = earDiff <= 1e-4;
    const marPassed = marDiff <= 1e-4;
    const closedPassed = isClosed === py.is_closed;

    totalAssertions += 3;
    if (earPassed) passedAssertions++;
    if (marPassed) passedAssertions++;
    if (closedPassed) passedAssertions++;

    console.log(
      `| ${name.padEnd(12)} | EAR    | ${py.weighted_ear.toFixed(5).padStart(10)} | ${weightedEar.toFixed(5).padStart(10)} | ${earDiff.toFixed(6).padStart(13)} | <= 1e-4   | ${earPassed ? "MATCH [OK]" : "MISMATCH"} |`
    );
    console.log(
      `| ${name.padEnd(12)} | MAR    | ${py.mar.toFixed(5).padStart(10)} | ${mar.toFixed(5).padStart(10)} | ${marDiff.toFixed(6).padStart(13)} | <= 1e-4   | ${marPassed ? "MATCH [OK]" : "MISMATCH"} |`
    );
    console.log(
      `| ${name.padEnd(12)} | Closed | ${String(py.is_closed).padStart(10)} | ${String(isClosed).padStart(10)} | ${"0".padStart(13)} | Exact Bool| ${closedPassed ? "MATCH [OK]" : "MISMATCH"} |`
    );
  }

  console.log("==========================================================================================================");
  console.log(`Max Observed EAR Difference: ${maxEarDiff.toExponential(3)}`);
  console.log(`Max Observed MAR Difference: ${maxMarDiff.toExponential(3)}`);
  console.log(`Total Parity Assertions Passed: ${passedAssertions}/${totalAssertions} (${((passedAssertions / totalAssertions) * 100).toFixed(1)}%)`);

  if (passedAssertions !== totalAssertions) {
    console.error("[DriveGuard] Cross-language parity verification failed!");
    process.exit(1);
  }

  console.log("[DriveGuard] Cross-language parity verification SUCCESSFUL: Exact mathematical parity verified!");
}

runParityVerification().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
